/* P7.9: purely visual, event-driven Sample Database rack connector.
 * Does not touch the sample library, audio graph or the rack layout. */
function __XenSampleRackRays({open}) {
  const [paths,setPaths]=P.useState([]);
  P.useEffect(()=>{
    if(!open){setPaths([]);return;}
    let frame=0, alive=true;
    const measure=()=>{
      frame=0;
      if(!alive)return;
      const button=document.querySelector('[data-xen-sample-database-trigger]');
      const rack=document.getElementById('melodic-sample-database-panel');
      if(!button||!rack){setPaths([]);return;}
      const a=button.getBoundingClientRect(),b=rack.getBoundingClientRect();
      if(a.width<2||b.width<2||b.top<=a.bottom+6){setPaths([]);return;}
      const origin=a.left+a.width/2;
      const target=Math.max(b.left+32,Math.min(b.right-32,origin));
      const y0=a.bottom+2,y1=b.top+1;
      const fans=[[-Math.min(24,a.width*.3),-29],[0,0],[Math.min(24,a.width*.3),29]];
      setPaths(old=>{
        const next=fans.map(([dx,spread])=>`M ${(origin+dx).toFixed(1)} ${y0.toFixed(1)} L ${(target+spread).toFixed(1)} ${y1.toFixed(1)}`);
        return old.length===next.length&&old.every((v,i)=>v===next[i])?old:next;
      });
    };
    const schedule=()=>{if(!frame)frame=requestAnimationFrame(measure)};
    const button=document.querySelector('[data-xen-sample-database-trigger]');
    const rack=document.getElementById('melodic-sample-database-panel');
    const observer=typeof ResizeObserver==='function'?new ResizeObserver(schedule):null;
    if(button)observer?.observe(button);
    if(rack)observer?.observe(rack);
    window.addEventListener('resize',schedule,{passive:true});
    window.addEventListener('scroll',schedule,{capture:true,passive:true});
    schedule();
    return ()=>{
      alive=false;
      if(frame)cancelAnimationFrame(frame);
      observer?.disconnect();
      window.removeEventListener('resize',schedule);
      window.removeEventListener('scroll',schedule,true);
    };
  },[open]);
  if(!open||!paths.length)return null;
  return u.jsx('svg',{
    'aria-hidden':'true',
    'data-xen-sample-database-rays':'open',
    style:{position:'fixed',top:0,left:0,width:'100vw',height:'100vh',zIndex:22,overflow:'visible',pointerEvents:'none'},
    children:paths.map((d,i)=>u.jsx('path',{d,fill:'none',stroke:'#77b6c4',strokeWidth:i===1?1.15:.85,opacity:i===1?.56:.34,strokeLinecap:'round'},i))
  });
}
